+    #[test]
+    fn the_invite_is_a_url_with_the_secrets_in_the_fragment_and_never_the_token() {
+        let id = identity();
+        let v4 = super::super::remote::pairing_invite(&id, "192.168.1.9:43187", "abcd2345");
+        assert_eq!(
+            v4,
+            format!(
+                "https://192.168.1.9:43187/#code=ABCD2345&key={}&id={}",
+                id.spki_sha256, id.server_id
+            )
+        );
+        let v6 = super::super::remote::pairing_invite(&id, "fe80::1:43187", "ABCD2345");
+        assert!(v6.starts_with("https://[fe80::1]:43187/#code="), "{v6}");
+        let kept = super::super::remote::pairing_invite(&id, "[fe80::1]:43187", "ABCD2345");
+        assert_eq!(v6, kept);
+        // The fragment is the only place the secrets go: nothing before
+        // the `#` carries them, and the token is never in an invite.
+        let before = v4.split('#').next().unwrap();
+        assert!(!before.contains(&id.spki_sha256));
+        assert!(!v4.contains("token"));
+    }
+
+    #[test]
+    fn the_token_cookie_name_is_per_host() {
+        let id = identity();
+        assert_eq!(
+            super::super::remote::token_cookie_name(&id),
+            format!("switchboard_token_{}", id.server_id)
+        );
+        let other = identity();
+        assert_ne!(
+            super::super::remote::token_cookie_name(&id),
+            super::super::remote::token_cookie_name(&other)
